 g.push({type:'polyline',shape:{points:line},style:{stroke:hexA(col,0.7),lineWidth:2,shadowColor:hexA(col,0.4),shadowBlur:6},silent:true,z:2});
 const lp=line[line.length-1];g.push({type:'circle',shape:{cx:lp[0],cy:lp[1],r:2.6},style:{fill:'#fff',stroke:col,lineWidth:1.5},silent:true,z:3});
}
// state pill (top-right, right-anchored, lightened text for contrast)
const pT=st.txt, pFS=Math.max(9,Math.min(11,ch*0.062));
const pW=Math.ceil(pT.length*pFS*0.92)+22, pH=pFS+13, pX=Math.max(cx+14,cx+cw-14-pW), pY=cy+13;
g.push({type:'rect',shape:{x:pX,y:pY,width:pW,height:pH,r:pH/2},style:{fill:hexA(col,0.17),stroke:hexA(col,0.45),lineWidth:1}});
g.push({type:'text',style:{x:pX+pW/2,y:pY+pH/2,text:pT,fill:lighten(col,0.42),font:'700 '+pFS+'px '+FONT,textAlign:'center',textVerticalAlign:'middle'}});
// big value + unit + note (upper-left cluster)
const valStr=(CFG.signed&&val>0?'+':'')+val.toFixed(CFG.decimals);
const valFS=Math.round(Math.min(ch*0.40,cw*0.34,50));
const valX=cx+22, valY=cy+ch*0.42;
g.push({type:'text',left:valX,top:valY,style:{text:valStr,fill:col,font:'800 '+valFS+'px '+FONT,textAlign:'left',textVerticalAlign:'middle',shadowColor:hexA(col,0.30),shadowBlur:6}});
if(CFG.unit){const uFS=Math.round(valFS*0.40),estW=valStr.length*valFS*0.56;g.push({type:'text',left:valX+estW+8,top:valY-valFS*0.04,style:{text:CFG.unit,fill:hexA(col,0.85),font:'600 '+uFS+'px '+FONT,textAlign:'left',textVerticalAlign:'middle'}});}
if(CFG.note){const nFS=Math.max(12,Math.round(valFS*0.30));g.push({type:'text',left:valX+1,top:valY+valFS*0.70+nFS*0.4,style:{text:CFG.note,fill:'#9aa2ac',font:'500 '+nFS+'px '+FONT,textAlign:'left',textVerticalAlign:'middle'}});}
// range track (bottom): grey bar, fill-to-marker, good-zone, zone-edge ticks, marker + now-tick, end labels
const tX0=cx+22,tX1=cx+cw-22,tY=cy+ch-28,tH=7;
const sc=(v)=>tX0+(Math.max(CFG.min,Math.min(v,CFG.max))-CFG.min)/(CFG.max-CFG.min)*(tX1-tX0);
g.push({type:'rect',shape:{x:tX0,y:tY,width:tX1-tX0,height:tH,r:tH/2},style:{fill:'rgba(255,255,255,0.07)'}});
const mx2=sc(val);
