g.push({type:'rect',shape:{x:Math.min(zA,zB)-0.75,y:tY-2,width:1.5,height:tH+4},style:{fill:hexA(GOOD,0.6)}});
g.push({type:'rect',shape:{x:Math.max(zA,zB)-0.75,y:tY-2,width:1.5,height:tH+4},style:{fill:hexA(GOOD,0.6)}});
g.push({type:'rect',shape:{x:mx2-0.9,y:tY-9,width:1.8,height:9},style:{fill:hexA(col,0.55)}});
g.push({type:'circle',shape:{cx:mx2,cy:tY+tH/2,r:tH*0.95},style:{fill:'#fff',stroke:col,lineWidth:2.5,shadowColor:hexA(col,0.55),shadowBlur:7}});
const lFS=Math.max(11,Math.round(ch*0.06));
const fmtB=(v)=>(CFG.signed&&v>0?'+':'')+v;
g.push({type:'text',left:tX0+1,top:tY+tH+4,style:{text:fmtB(CFG.min),fill:'#9aa3ad',font:'500 '+lFS+'px '+FONT,textAlign:'left',textVerticalAlign:'top'}});
g.push({type:'text',right:m+22,top:tY+tH+4,style:{text:fmtB(CFG.max),fill:'#9aa3ad',font:'500 '+lFS+'px '+FONT,textAlign:'right',textVerticalAlign:'top'}});
return {backgroundColor:'transparent',animation:false,textStyle:{fontFamily:FONT},graphic:g};
